import React, { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { Mic, MicOff, Volume2, Download } from "lucide-react";

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:5000";

const VoiceAssistant = () => {
  const [isListening, setIsListening] = useState(false);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [responses, setResponses] = useState({});
  const [generatedContent, setGeneratedContent] = useState("");
  const [conversationComplete, setConversationComplete] = useState(false);
  const [conversationStarted, setConversationStarted] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState("");
  const [estimatedTime, setEstimatedTime] = useState(0);

  const recognitionRef = useRef(null);
  const synthRef = useRef(null);
  const transcriptRef = useRef("");
  const abortControllerRef = useRef(null);

  const questions = [
    "What topic would you like to create content about?",
    "Which platform are you targeting? Instagram, Twitter, LinkedIn, YouTube, or Facebook?",
    "What is your goal? Educate, entertain, inspire, or promote?",
    "Who is your target audience? Beginners, professionals, or general audience?",
    "How long should the content be? Short, medium, or detailed?"
  ];

  /* ---------------- INIT SPEECH APIS ---------------- */
  useEffect(() => {
    if ("SpeechRecognition" in window || "webkitSpeechRecognition" in window) {
      const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
      recognitionRef.current = new SR();
      recognitionRef.current.lang = "en-US";
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (e) => {
        const text = e.results[0][0].transcript.trim();
        transcriptRef.current = text;
        setTranscript(text);
        stopListening();
        processResponse(text);
      };

      recognitionRef.current.onerror = () => stopListening();
      recognitionRef.current.onend = () => {
        if (
          !transcriptRef.current &&
          conversationStarted &&
          !conversationComplete
        ) {
          setTimeout(startListening, 1000);
        }
      };
    }

    synthRef.current = window.speechSynthesis;

    return () => {
      recognitionRef.current?.stop();
      synthRef.current?.cancel();
      abortControllerRef.current?.abort();
    };
  }, []);

  /* ---------------- SPEAK ---------------- */
  const speak = (text) => {
    if (!synthRef.current) return;
    synthRef.current.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.rate = 0.9;
    synthRef.current.speak(u);
  };

  /* ---------------- LISTEN ---------------- */
  const startListening = () => {
    if (!recognitionRef.current || isListening) return;
    try {
      transcriptRef.current = "";
      setTranscript("");
      setIsListening(true);
      recognitionRef.current.stop();
      recognitionRef.current.start();

      setTimeout(() => stopListening(), 10000);
    } catch {}
  };

  const stopListening = () => {
    try {
      recognitionRef.current?.stop();
    } catch {}
    setIsListening(false);
  };

  /* ---------------- PROCESS RESPONSE ---------------- */
  const processResponse = (response) => {
    const updated = { ...responses };
    const r = response.toLowerCase();

    if (currentQuestion === 0) updated.topic = response;
    if (currentQuestion === 1)
      updated.platform =
        ["instagram", "twitter", "linkedin", "youtube", "facebook"].find(p =>
          r.includes(p)
        ) || "instagram";

    if (currentQuestion === 2)
      updated.goal =
        r.includes("entertain")
          ? "entertaining"
          : r.includes("inspire")
          ? "inspirational"
          : r.includes("promote")
          ? "promotional"
          : "educational";

    if (currentQuestion === 3)
      updated.audience =
        r.includes("professional")
          ? "professionals"
          : r.includes("beginner")
          ? "beginners"
          : "general";

    if (currentQuestion === 4)
      updated.length =
        r.includes("short") ? "short" : r.includes("detail") ? "long" : "medium";

    setResponses(updated);

    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion((q) => q + 1);
    } else {
      speak("Thank you. Generating your content now.");
      generateContent(updated);
    }
  };

  /* ---------------- GENERATE CONTENT ---------------- */
  const generateContent = async (data) => {
    setIsProcessing(true);
    setEstimatedTime(15);
    setProcessingStep("Connecting to AI engine...");
    abortControllerRef.current = new AbortController();

    try {
      const res = await fetch(`${API_URL}/api/voice-generate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
        signal: abortControllerRef.current.signal
      });

      const json = await res.json();

      if (!json.success) throw new Error("Generation failed");

      setGeneratedContent(json.content);
      setConversationComplete(true);
      speak("Your content is ready.");

    } catch {
      setGeneratedContent(`# ${data.topic}\n\nContent generated using fallback.`);
      setConversationComplete(true);
    } finally {
      setIsProcessing(false);
    }
  };

  /* ---------------- UI ---------------- */
  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-900 to-purple-900 p-6 text-white">
      <div className="max-w-4xl mx-auto space-y-6">

        <h1 className="text-4xl font-bold text-center">🎤 Voice Assistant</h1>

        {!conversationComplete ? (
          <>
            {!conversationStarted ? (
              <button
                onClick={() => {
                  setConversationStarted(true);
                  speak(questions[0]);
                  setTimeout(startListening, 4000);
                }}
                className="mx-auto block px-8 py-4 bg-pink-500 rounded-full font-bold"
              >
                Start Conversation
              </button>
            ) : (
              <div className="bg-white/10 p-6 rounded-xl">
                <p className="text-lg mb-4">{questions[currentQuestion]}</p>

                <div className="flex justify-center gap-2">
                  {isListening ? <Mic /> : <MicOff />}
                  {isListening ? "Listening..." : "Waiting"}
                </div>

                {transcript && (
                  <p className="mt-4 text-gray-300">You said: "{transcript}"</p>
                )}
              </div>
            )}
          </>
        ) : (
          <div className="bg-white/10 p-6 rounded-xl">
            <h2 className="text-2xl font-bold mb-4">Generated Content</h2>
            <pre className="whitespace-pre-wrap">{generatedContent}</pre>

            <div className="flex gap-4 mt-4">
              <button
                onClick={() => speak(generatedContent.slice(0, 400))}
                className="px-4 py-2 bg-blue-500 rounded-full flex gap-2"
              >
                <Volume2 /> Read
              </button>

              <button
                onClick={() => {
                  const blob = new Blob([generatedContent], { type: "text/plain" });
                  const a = document.createElement("a");
                  a.href = URL.createObjectURL(blob);
                  a.download = "voice_content.txt";
                  a.click();
                }}
                className="px-4 py-2 bg-green-500 rounded-full flex gap-2"
              >
                <Download /> Download
              </button>
            </div>
          </div>
        )}

        {isProcessing && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center">
            <div className="bg-white/10 p-6 rounded-xl text-center">
              <div className="animate-spin h-10 w-10 border-4 border-pink-500 border-t-transparent rounded-full mx-auto mb-4" />
              <p>{processingStep}</p>
              <p className="text-sm">{estimatedTime}s remaining</p>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default VoiceAssistant;
